// Snapshot Supabase auth-callback params from the URL before the client consumes them,
// so we can tell the candidate whether an email link succeeded, expired, or was invalid.
const authCallbackParams=(()=>{try{const q=new URLSearchParams(window.location.search);const h=new URLSearchParams(window.location.hash.replace(/^#/,''));const g=(k:string)=>q.get(k)??h.get(k);return{type:g('type')||'',error:g('error')||'',errorCode:g('error_code')||'',errorDescription:g('error_description')||''}}catch{return{type:'',error:'',errorCode:'',errorDescription:''}}})();

