type Job={id:string;title:string;description:string|null;qualifications:string|null;is_active:boolean;created_at?:string};
type Application={id:string;user_id:string;job_id:string;status:string;progress_percent:number;form_data:Record<string,any>;created_at:string;updated_at:string;submitted_at?:string|null};
