type Route={name:'home'}|{name:'job';id:string};
const blankCompanyConfig=():CompanyConfig=>({welfare:'',contact_department:'',contact_company_name:'',contact_address:'',contact_phone1:'',contact_phone1_note:'',contact_phone2:'',contact_email:'',contact_website:'',contact_line_id:'',location_name:'',location_address:'',location_maps_url:''});
// Stable, order-independent share URL: every posting keeps the same /job/<uuid> link forever.
function parseRoute(path:string):Route{const m=path.match(/^\/job\/([0-9a-fA-F-]{36})\/?$/);return m?{name:'job',id:m[1]}:{name:'home'}}
