function AppFooter(){return <footer className="footer no-print"><div>© 2026 STAR LIVE ONLINE · JOB-APPLICATION · ระบบกรอกใบสมัครงานออนไลน์ (V2.0) | ติดต่อผู้พัฒนา LINE ID: <a href="https://line.me/ti/p/~dj_nodoubt" target="_blank" rel="noopener noreferrer">dj_nodoubt</a></div></footer>}
async function printA4(a:Application,job:string){
  // Open before awaiting so browser popup blockers do not prevent printing.
  const w=window.open('about:blank','_blank');
  if(!w){window.alert('เบราว์เซอร์บล็อกหน้าต่างพิมพ์ กรุณาอนุญาต Pop-up สำหรับเว็บไซต์นี้แล้วลองอีกครั้ง');return;}
  let photoUrl:string|undefined;
  if(supabase){
    try{
      const{data:document}=await supabase.from('application_documents').select('storage_path').eq('application_id',a.id).eq('document_type','profile_photo').maybeSingle();
      if(document?.storage_path){
        const{data}=await supabase.storage.from('candidate-photos').createSignedUrl(document.storage_path,300);
        photoUrl=data?.signedUrl;
      }
    }catch{
      // Keep printing available when a photo is absent or RLS denies photo access.
    }
  }
  const payload={data:a.form_data||{},job,applicationId:a.id,submittedAt:a.submitted_at||a.updated_at||a.created_at,...(photoUrl?{photoUrl}:{})};
  w.name=JSON.stringify(payload);
  w.location.href=new URL('/application-template.html',window.location.origin).toString();
}
